repro.command:
bash -c 'tmp=$(mktemp -d); trap "rm -rf $tmp" EXIT; printf "package migrate
import ("os";"path/filepath";"testing")
func TestReproSymlinkEscape(t *testing.T){
	out:=t.TempDir(); sec:=filepath.Join(out,"s.dump"); _=os.WriteFile(sec,[]byte("x"),0o600); sum,_:=FileChecksum(sec)
	bak:=t.TempDir(); vd:=filepath.Join(bak,"volumes"); _=os.MkdirAll(vd,0o700); _=os.Symlink(sec,filepath.Join(vd,"db.dump"))
	m:=NewManifest("1.0"); m.AddVolume(VolumeBackup{Name:"db",Type:BackupTypePostgreSQL,Filename:"volumes/db.dump",Size:1,Checksum:sum}); m.Finalize()
	if err:=m.Verify(bak); err==nil { t.Fatal("symlink escaped backupDir") }
}
" > "$tmp/repro_test.go"; printf "{"Replace":{"%s/internal/migrate/repro_overlay_test.go":"%s/repro_test.go"}}" "$(cd altctl && pwd)" "$tmp" > "$tmp/ov.json"; go -C altctl test -overlay="$tmp/ov.json" -run TestReproSymlinkEscape ./internal/migrate'

bash -c 'tmp=$(mktemp -d); trap "rm -rf $tmp" EXIT; printf "package setup
import ("os";"path/filepath";"testing")
func TestReproEnvSymlink(t *testing.T){
	victim:=filepath.Join(t.TempDir(),"victim"); proj:=t.TempDir()
	_=os.WriteFile(filepath.Join(proj,".env.example"),[]byte("A=1"),0o600); _=os.Symlink(victim,filepath.Join(proj,".env"))
	_,_=CreateEnvFile(proj,false)
	if _,err:=os.Stat(victim); err==nil { t.Fatal("CreateEnvFile wrote through dangling symlink outside projectRoot") }
}
" > "$tmp/repro_test.go"; printf "{"Replace":{"%s/internal/setup/repro_overlay_test.go":"%s/repro_test.go"}}" "$(cd altctl && pwd)" "$tmp" > "$tmp/ov.json"; go -C altctl test -overlay="$tmp/ov.json" -run TestReproEnvSymlink ./internal/setup'
